#!/usr/bin/env bun
import { writeFileSync } from 'node:fs'
import { join, relative } from 'node:path'

import { readTopicSources } from './read-sources'

// Compiles `topics/**/*.md` into `sources.generated.ts` — `bun run docs:mcp`.
//
// The docs are authored as Markdown so they read on GitHub and diff like prose,
// but the MCP is served from a Worker, where there is no filesystem to read them
// from at request time and no bundler rule we can count on for `.md` imports
// across every host. So they are embedded as strings. `docs.test.ts` fails when
// the generated file and the sources disagree.

const body = Object.entries(readTopicSources())
  .map(([id, text]) => `  ${JSON.stringify(id)}: ${JSON.stringify(text)},`)
  .join('\n')

const target = join(import.meta.dirname, 'sources.generated.ts')
writeFileSync(
  target,
  `// GENERATED by \`bun run docs:mcp\` from src/mcp/docs/topics/**/*.md — do not edit.

export const DOC_SOURCES: Record<string, string> = {
${body}
}
`,
)
process.stdout.write(`[007] wrote ${relative(process.cwd(), target)}\n`)
